package au.aumanet.app;

import java.util.*;
import org.json.*;

/** Actual persisted-permission/run classes with fault-injected storage, no
 * Android permission/Wi-Fi/FGS/Keystore/media or physical acceptance claim. */
public final class TrustedConnectionPolicyTest {
    static int tests,checks;static final String SELF="AB".repeat(32),OWNER="CD".repeat(32),OTHER="EF".repeat(32),GROUP="a".repeat(32),ATTACHMENT="12".repeat(32),PROCESS="12345678-1234-1234-1234-123456789abc";
    static final Object source=new Object();
    interface Checked {void run()throws Exception;}
    static void check(boolean value){checks++;if(!value)throw new AssertionError("check "+checks);}
    static void fails(Checked work)throws Exception{boolean failed=false;try{work.run();}catch(Exception expected){failed=true;}check(failed);}
    static TrustedConnectionScope scope(){return scope(source,PROCESS,SELF,GROUP,OWNER,1,7,List.of(SELF,OWNER),true,false);}
    static TrustedConnectionScope scope(Object source,String process,String self,String group,String owner,long epoch,long run,Collection<String> members,boolean saved,boolean live){return new TrustedConnectionScope(source,process,self,group,owner,epoch,run,members,saved,live,false);}
    static final class Memory implements TrustedConnectionStore.Storage {String text;int writes;boolean failBefore,failAfter,badReadback;String old;public String read(){return badReadback?old:text;}public boolean write(String next)throws Exception{writes++;if(failBefore)throw new java.io.IOException("before");old=text;text=next;if(failAfter)throw new java.io.IOException("durable unknown");return true;}}
    static TrustedConnectionStore.Record remembered(TrustedConnectionStore store)throws Exception{return store.remember(scope(),ATTACHMENT,"ptt-ready",0,0,"b".repeat(32));}
    public static void main(String[] args)throws Exception{
        tests++;Memory memory=new Memory();TrustedConnectionStore store=new TrustedConnectionStore(memory);check(store.current()==null);TrustedConnectionRun fence=new TrustedConnectionRun();check(fence.current()==null);TrustedConnectionStore.Record record=remembered(store);check(memory.writes==1&&record.revision==1&&record.enabled&&record.voice.equals("ptt-ready"));check(fence.current()==null);
        tests++;TrustedConnectionStore reopened=new TrustedConnectionStore(memory);check(reopened.current().digest.equals(record.digest));check(new TrustedConnectionRun().current()==null);check(reopened.current().matches(scope(),ATTACHMENT,0));
        tests++;check(store.remember(scope(),ATTACHMENT,"ptt-ready",0,0,"b".repeat(32))==record);check(memory.writes==1);fails(()->store.remember(scope(),ATTACHMENT,"muted",0,0,"b".repeat(32)));fails(()->store.remember(scope(),ATTACHMENT,"ptt-ready",0,0,"c".repeat(32)));check(memory.writes==1);
        tests++;for(TrustedConnectionScope changed:List.of(scope(new Object(),PROCESS,OTHER,GROUP,OWNER,1,7,List.of(OTHER,OWNER),true,false),scope(source,PROCESS,SELF,"d".repeat(32),OWNER,1,7,List.of(SELF,OWNER),true,false),scope(source,PROCESS,SELF,GROUP,OTHER,1,7,List.of(SELF,OTHER),true,false),scope(source,PROCESS,SELF,GROUP,OWNER,2,7,List.of(SELF,OWNER),true,false),scope(source,PROCESS,SELF,GROUP,OWNER,1,7,List.of(SELF,OWNER,OTHER),true,false)))check(!record.matches(changed,ATTACHMENT,0));check(!record.matches(scope(),"34".repeat(32),0));check(!record.matches(scope(),ATTACHMENT,5));
        tests++;TrustedConnectionScope otherRuntime=scope(new Object(),"22345678-1234-1234-1234-123456789abc",SELF,GROUP,OWNER,1,9,List.of(OWNER,SELF),true,false);check(record.matches(otherRuntime,ATTACHMENT,0));check(!scope().sameRun(otherRuntime));check(scope().sameAuthority(otherRuntime));check(scope().rosterDigest().equals(otherRuntime.rosterDigest()));
        tests++;TrustedConnectionRun.Run first=fence.start("1".repeat(32),1000,record,scope());check(fence.owns(first,1001));check(first.voiceAllowed.get()&&first.readinessAllowed.get());fails(()->fence.start("2".repeat(32),1002,record,scope()));check(fence.disarm("f".repeat(32),first.generation)==null);check(fence.owns(first,1003));check(fence.disarm(first.id,first.generation)==first);check(!first.voiceAllowed.get()&&!first.readinessAllowed.get());TrustedConnectionRun.Run second=fence.start("2".repeat(32),2000,record,scope());check(fence.disarm(first.id,first.generation)==null);check(fence.owns(second,2001));
        tests++;TrustedConnectionScope after=scope(source,PROCESS,SELF,GROUP,OWNER,1,8,List.of(SELF,OWNER),true,false);check(fence.transportTransition(second,scope(),after));check(second.scope==after);check(!fence.transportTransition(second,scope(),scope()));check(!fence.transportTransition(first,scope(),after));check(!fence.transportTransition(second,after,otherRuntime));
        tests++;check(!fence.owns(second,second.deadline));check(!fence.owns(second,second.deadline-1));check(!second.voiceAllowed.get()&&!second.readinessAllowed.get());fence.disarm();TrustedConnectionRun.Run third=fence.start("3".repeat(32),5000,record,scope());check(!fence.owns(third,4999));check(!fence.owns(third,5001));
        tests++;for(String mode:List.of("off","muted","ptt-ready")){Memory m=new Memory();TrustedConnectionStore s=new TrustedConnectionStore(m);TrustedConnectionStore.Record r=s.remember(scope(),ATTACHMENT,mode,0,0,"c".repeat(32));TrustedConnectionRun.Run run=new TrustedConnectionRun().start("e".repeat(32),1,r,scope());check(run.voiceAllowed.get()==!mode.equals("off"));check(run.readinessAllowed.get()==mode.equals("ptt-ready"));}fails(()->store.remember(scope(),ATTACHMENT,"vad",0,1,"c".repeat(32)));
        tests++;TrustedConnectionStore.Record forgotten=store.forget(1,"c".repeat(32));check(!forgotten.enabled&&forgotten.voice.equals("off")&&forgotten.revision==2);fails(()->new TrustedConnectionRun().start("f".repeat(32),1,forgotten,scope()));check(new TrustedConnectionStore(memory).current().revision==2);
        tests++;Memory unknown=new Memory();TrustedConnectionStore uncertain=new TrustedConnectionStore(unknown);unknown.failAfter=true;fails(()->remembered(uncertain));check(unknown.text!=null);fails(uncertain::current);unknown.failAfter=false;fails(()->remembered(uncertain));check(unknown.writes==1);check(new TrustedConnectionStore(unknown).current().enabled);check(new TrustedConnectionRun().current()==null);
        tests++;Memory readback=new Memory();TrustedConnectionStore readbackStore=new TrustedConnectionStore(readback);readback.badReadback=true;fails(()->remembered(readbackStore));fails(readbackStore::current);check(readback.writes==1);
        tests++;for(String malformed:List.of(memory.text+" trailing",memory.text.substring(0,memory.text.length()-1)+",\"enabled\":true}",memory.text.replace("\"voice\":\"off\"","\"voice\":\"vad\""),memory.text.replace("\"revision\":2","\"revision\":\"2\""),memory.text.replace("\"epoch\":1","\"epoch\":1.5"),memory.text.replace("\"schema\":\"aumanet.trusted-connection.v1\"","\"schema\":\"unknown\""))){Memory bad=new Memory();bad.text=malformed;fails(()->new TrustedConnectionStore(bad));}
        tests++;fails(()->scope(source,PROCESS,SELF,GROUP,OWNER,1,1,List.of(SELF,SELF,OWNER),true,false));fails(()->scope(source,PROCESS,SELF,GROUP,OWNER,1,1,List.of(SELF),true,false));fails(()->scope(source,PROCESS,SELF,GROUP,OWNER,TrustedConnectionScope.MAX_REVISION+1,1,List.of(SELF,OWNER),true,false));TrustedConnectionScope unsaved=scope(source,PROCESS,SELF,GROUP,OWNER,1,1,List.of(SELF,OWNER),false,false);fails(()->new TrustedConnectionStore(new Memory()).remember(unsaved,ATTACHMENT,"off",0,0,"b".repeat(32)));
        tests++;Memory ownerMemory=new Memory();TrustedConnectionStore ownerStore=new TrustedConnectionStore(ownerMemory);TrustedConnectionStore.Record ownerPolicy=ownerStore.remember(scope(),ATTACHMENT,"off",5,0,"b".repeat(32));check(ownerPolicy.gatewayRevision==5);check(ownerPolicy.matches(scope(),ATTACHMENT,5));check(!ownerPolicy.matches(scope(),ATTACHMENT,6));check(new TrustedConnectionStore(ownerMemory).current().gatewayRevision==5);
        tests++;Memory legacy=new Memory();JSONObject legacyJson=new JSONObject(unknown.text);legacyJson.remove("shareLocation");legacy.text=legacyJson.toString();TrustedConnectionStore.Record oldPolicy=new TrustedConnectionStore(legacy).current();check(!oldPolicy.shareLocation);check(!new TrustedConnectionRun().start("a".repeat(32),1,oldPolicy,scope()).locationAllowed.get());
        tests++;Memory geo=new Memory();TrustedConnectionStore geoStore=new TrustedConnectionStore(geo);TrustedConnectionStore.Record geoPolicy=geoStore.remember(scope(),ATTACHMENT,"muted",true,0,0,"b".repeat(32));check(geoPolicy.shareLocation);check(new TrustedConnectionStore(geo).current().shareLocation);TrustedConnectionRun geoRun=new TrustedConnectionRun();TrustedConnectionRun.Run active=geoRun.start("a".repeat(32),1,geoPolicy,scope());check(active.locationAllowed.get());geoRun.disarm();check(!active.locationAllowed.get());fails(()->geoStore.remember(scope(),ATTACHMENT,"muted",false,0,0,"b".repeat(32)));JSONObject invalid=new JSONObject(geo.text).put("shareLocation","true");Memory badGeo=new Memory();badGeo.text=invalid.toString();fails(()->new TrustedConnectionStore(badGeo));check(!geoStore.forget(1,"c".repeat(32)).shareLocation);
        System.out.println(new JSONObject().put("status","passed").put("testCount",tests).put("assertionCount",checks).put("physical",false));
    }
}
